import java.util.ArrayList;
import java.util.List;

// Model: plain data, no formatting logic and no printing here at all
class Task {
    private String title;
    private boolean done;

    public Task(String title) {
        this.title = title;
        this.done = false;
    }

    public String getTitle() {
        return title;
    }

    public boolean isDone() {
        return done;
    }

    public void markDone() {
        this.done = true;
    }
}

// Model: owns the collection and the one rule that matters here, adding a task
class TaskModel {
    private final List<Task> tasks = new ArrayList<>();

    public Task addTask(String title) {
        Task task = new Task(title);
        tasks.add(task);
        return task;
    }

    public List<Task> getTasks() {
        return tasks;
    }
}

// View: only knows how to format and print, never touches storage directly
class TaskView {
    public void renderTaskList(List<Task> tasks) {
        System.out.println("Task Board");
        for (Task task : tasks) {
            String status = task.isDone() ? "done" : "pending";
            System.out.println("- " + task.getTitle() + " [" + status + "]");
        }
    }

    public void renderConfirmation(String title) {
        System.out.println("Created task: " + title);
    }
}

// Controller: the only class allowed to know about both the Model and the View
class TaskController {
    private final TaskModel model;
    private final TaskView view;

    public TaskController(TaskModel model, TaskView view) {
        this.model = model;
        this.view = view;
    }

    // handles a create task request end to end
    public void createTask(String title) {
        model.addTask(title);           // step 1: update the Model
        view.renderConfirmation(title); // step 2: ask the View to render
        view.renderTaskList(model.getTasks());
    }
}

// controlled entry point that wires Model, View and Controller together
public class Main {
    public static void main(String[] args) {
        TaskModel model = new TaskModel();
        TaskView view = new TaskView();
        TaskController controller = new TaskController(model, view);

        controller.createTask("Write the MVC topic doc");
        controller.createTask("Review the pull request");
    }
}

