#include <iostream>
#include <string>
#include <vector>
using namespace std;

// Model: plain data, no formatting logic and no printing here at all
class Task {
public:
    string title;
    bool done;

    Task(string t) : title(t), done(false) {}

    void markDone() {
        done = true;
    }
};

// Model: owns the collection and the one rule that matters here, adding a task
class TaskModel {
public:
    vector<Task> tasks;

    Task& addTask(string title) {
        tasks.push_back(Task(title));
        return tasks.back();
    }

    vector<Task>& getTasks() {
        return tasks;
    }
};

// View: only knows how to format and print, never touches storage directly
class TaskView {
public:
    void renderTaskList(vector<Task>& tasks) {
        cout << "Task Board" << endl;
        for (Task& task : tasks) {
            string status = task.done ? "done" : "pending";
            cout << "- " << task.title << " [" << status << "]" << endl;
        }
    }

    void renderConfirmation(string title) {
        cout << "Created task: " << title << endl;
    }
};

// Controller: the only class allowed to know about both the Model and the View
class TaskController {
public:
    TaskModel& model;
    TaskView& view;

    TaskController(TaskModel& m, TaskView& v) : model(m), view(v) {}

    // handles a create task request end to end
    void createTask(string title) {
        model.addTask(title);           // step 1: update the Model
        view.renderConfirmation(title); // step 2: ask the View to render
        view.renderTaskList(model.getTasks());
    }
};

// controlled entry point that wires Model, View and Controller together
int main() {
    TaskModel model;
    TaskView view;
    TaskController controller(model, view);

    controller.createTask("Write the MVC topic doc");
    controller.createTask("Review the pull request");

    return 0;
}
